window.ScripturaLexicons.BDAG_PART_0267 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-01\" data-source=\"BDAG\" data-search=\"πανπληθής remissão ver παμπληθής BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πανπληθής</td><td>remissão</td><td>ver παμπληθής</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-02\" data-source=\"BDAG\" data-search=\"πάνσεμνος, ον adjetivo grandemente reverenciado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάνσεμνος, ον</td><td>adjetivo</td><td>grandemente reverenciado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-03\" data-source=\"BDAG\" data-search=\"πανταχῇ advérbio em toda parte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πανταχῇ</td><td>advérbio</td><td>em toda parte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-04\" data-source=\"BDAG\" data-search=\"πανταχόθεν advérbio de todas as direções BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πανταχόθεν</td><td>advérbio</td><td>de todas as direções</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-05\" data-source=\"BDAG\" data-search=\"πανταχοῦ advérbio em toda parte; em todas as direções BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πανταχοῦ</td><td>advérbio</td><td>em toda parte; em todas as direções</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-06\" data-source=\"BDAG\" data-search=\"παντελής, ές adjetivo completamente; para sempre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντελής, ές</td><td>adjetivo</td><td>completamente; para sempre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-07\" data-source=\"BDAG\" data-search=\"παντελῶς advérbio plenamente; inteiramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντελῶς</td><td>advérbio</td><td>plenamente; inteiramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-08\" data-source=\"BDAG\" data-search=\"παντεπόπτης, ου, ὁ substantivo masculino onividente; aquele que tudo vê BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντεπόπτης, ου, ὁ</td><td>substantivo masculino</td><td>onividente; aquele que tudo vê</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-09\" data-source=\"BDAG\" data-search=\"πάντῃ advérbio de todos os modos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάντῃ</td><td>advérbio</td><td>de todos os modos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-10\" data-source=\"BDAG\" data-search=\"πάντοθεν advérbio de todos os lados; completamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάντοθεν</td><td>advérbio</td><td>de todos os lados; completamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-11\" data-source=\"BDAG\" data-search=\"παντοκρατορικός, όν adjetivo onipotente; todo-poderoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντοκρατορικός, όν</td><td>adjetivo</td><td>onipotente; todo-poderoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-12\" data-source=\"BDAG\" data-search=\"παντοκράτωρ, ορος, ὁ substantivo masculino o Onipotente; o Todo-Poderoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντοκράτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>o Onipotente; o Todo-Poderoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-13\" data-source=\"BDAG\" data-search=\"παντοκτίστης, ου, ὁ substantivo masculino criador do universo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παντοκτίστης, ου, ὁ</td><td>substantivo masculino</td><td>criador do universo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-14\" data-source=\"BDAG\" data-search=\"πάντοτε advérbio sempre; em todos os momentos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάντοτε</td><td>advérbio</td><td>sempre; em todos os momentos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-15\" data-source=\"BDAG\" data-search=\"πάντως advérbio certamente; totalmente; de modo algum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάντως</td><td>advérbio</td><td>certamente; totalmente; de modo algum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-16\" data-source=\"BDAG\" data-search=\"πάνυ advérbio inteiramente; muito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάνυ</td><td>advérbio</td><td>inteiramente; muito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-17\" data-source=\"BDAG\" data-search=\"Παπίας, α nome próprio masculino Pápias de Hierápolis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Παπίας, α</td><td>nome próprio masculino</td><td>Pápias de Hierápolis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-18\" data-source=\"BDAG\" data-search=\"παρά preposição de; junto a; com; contra; além de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρά</td><td>preposição</td><td>de; junto a; com; contra; além de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-19\" data-source=\"BDAG\" data-search=\"παραβαίνω verbo desviar-se; transgredir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβαίνω</td><td>verbo</td><td>desviar-se; transgredir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0267-20\" data-source=\"BDAG\" data-search=\"παραβάλλω verbo lançar; expor; comparar; aproximar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβάλλω</td><td>verbo</td><td>lançar; expor; comparar; aproximar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0267-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανπληθής</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πανπληθής</span>: ver <span class=\"greek\">παμπληθής</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνσεμνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάνσεμνος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">σεμνός</span>; Lucian, Vit. Auct. 26, Anach. 9), grandemente reverenciado, venerabilíssimo: <span class=\"greek\">πνεῦμα</span>, Hv 1, 2, 4 (o texto não é seguro; ver MDibelius ad loc.).—Ver DELG s.v. <span class=\"greek\">πᾶς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανταχῇ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πανταχῇ</span> (sobre a forma, ver Schwyzer I 622; quanto à grafia, B-D-F §26; W-S. §5, 11c; Mlt.-H. 84; Meisterhans3-Schw. p. 145), advérbio (Hdt. e outros; Pla., Ep. 7, 335c <span class=\"greek\">πάντως</span> <span class=\"greek\">π</span>.; inscrições, papiros, LXX; Jos., Bell. 1, 149), em toda parte, por toda parte: <span class=\"greek\">πάντας</span> <span class=\"greek\">π</span>. <span class=\"greek\">διδάσκων</span>, «Que ensina a todos por toda parte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:28</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">κεκλημένων</span>, «Com todos os chamados, em toda parte», 1 Cl 65:2.—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανταχόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πανταχόθεν</span>, advérbio (Hdt., Thu., Pla. e outros; Diod S 17, 82, 3; Strabo 8, 6, 15; Jos., Ant. 4, 133; 12, 353; inscrições, papiros; 4 Macc 13:1; 15:32), de todas as direções, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>, variante textual (em lugar de <span class=\"greek\">πάντοθεν</span>).—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πανταχοῦ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πανταχοῦ</span> (sobre a forma, Schwyzer I 621), advérbio (Soph., Thu. e outros; papiros; Is 42:22; JosAs 3:10; Jos., Bell. 1, 165, Ant. 14, 137; Just.; Ath. 35, 2), relativo a posições em qualquer direção, em toda parte, por toda parte (assim quase sempre), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:22</a>; 1 Cl 41:2. <span class=\"greek\">πάντῃ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>., «Em todos os sentidos e em toda parte» (B-D-F §103; cf. Rob. 300), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:3</a>. Empregado em paronomásia com <span class=\"greek\">πᾶς</span> (B-D-F §488, 1a; Dio Chrys. 11 [12], 19; Philo, Aet. M. 68; Jos., Bell. 5, 310, Ant. 17, 143): <span class=\"greek\">ἀπαγγέλλει</span> … <span class=\"greek\">πάντας</span> <span class=\"greek\">π</span>. <span class=\"greek\">μετανοεῖν</span>, 17:30. <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ἐκκλησίᾳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>. Talvez com a nuance específica «em todas as direções», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:28</a> (assim Bauer, com referência a Aristoph., Lys. 1230; Lucian, Bis Accus. 27).—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντελής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντελής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">τέλος</span>; trágicos, Hdt. e posteriores; inscrições, papiros; 3 Macc 7:16; GrBar 4:10; Tat. 6, 1; Ath., R. 19 p. 72, 13 e outros), em nossa literatura na expressão <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>., em lugar do advérbio <span class=\"greek\">παντελῶς</span> (Philo, Joseph., Tat., Aelian).<br>\n① Relativo ao cumprimento de um padrão muito elevado de qualidade ou completude, completamente.<br>\nⓐ Quanto a uma ação, (inteiramente) completo, perfeito, absoluto, o mesmo que <span class=\"greek\">παντελῶς</span>, isto é, completamente, plenamente, inteiramente. A versão armênia entende <span class=\"greek\">σῴζειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">δύναται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a>, nesse sentido; também muitos intérpretes posteriores. <span class=\"greek\">μὴ</span> <span class=\"greek\">δυναμένη</span> <span class=\"greek\">ἀνακῦψαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:11</a>, é igualmente entendido por muitos nesse sentido: «Ela não conseguia endireitar-se completamente» (<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. nesse sentido em Aelian, NA 17, 27; Cyranides 57, 4; Philo, Leg. ad Gai. 144; Jos., Ant. 1, 267; 3, 264; 274; 6, 30; 7, 325).<br>\nⓑ Quanto à capacidade, completamente, de modo algum; assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:11</a>, se <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. for ligado a <span class=\"greek\">μὴ</span> <span class=\"greek\">δυναμένη</span>, em vez de <span class=\"greek\">ἀνακῦψαι</span>: «Ela era completamente incapaz de endireitar-se», isto é, «Não conseguia endireitar-se de modo algum» (Goodsp.; assim a Vulgata, mas a antiga tradução siríaca dos Evangelhos [tanto a sinaítica quanto a curetoniana] admite tanto este sentido quanto a acepção a acima.—Ael. Aristid. 26, 72 K. = 14 p. 351 D.: <span class=\"greek\">παράδειγμα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span>).<br>\n② Relativo a uma duração ilimitada de tempo, para sempre, por todo o tempo (Aelian, VH 7, 2; 12, 20 [paralelo a <span class=\"greek\">διὰ</span> <span class=\"greek\">τέλους</span>]; OGI 642, 2 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παντελὲς</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">τειμήν</span>; RB 39, ’30, 544, linhas 18f; 546, linha 6; PLond III, 1164 f, 11 p. 161 [212 d.C.]. Talvez Jos., Ant. 3, 274). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a> é entendido nesse sentido pela Vulgata, pelas versões siríaca e copta e por muitos intérpretes modernos, inclusive Rohr, Windisch, Montefiore, NRSV.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντελῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντελῶς</span>, advérbio (ver <span class=\"greek\">παντελής</span>; trágicos, Hdt. e posteriores; Polyb., Epict., inscrições, papiros; 2 Macc; TestSol 5:7 P; ApcSed 14:9 p. 136, 15 Ja.; EpArist, Philo; Jos., Ant. 4, 121; Just., A II, 10, 8; Ath., R. 20 p. 73, 11 e outros), no grau mais pleno, plenamente, completamente, inteiramente; nas respostas (cf. Pla., Rep. 2, 379b; 3, 401a; 6, 485d e outros): <span class=\"greek\">οὐ</span> <span class=\"greek\">παντελῶς</span>, «De modo algum; absolutamente não» (Lucian, Catapl. 4), Hs 7:4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντεπόπτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντεπόπτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πᾶς</span> [*<span class=\"greek\">παντ</span>], <span class=\"greek\">ἐπόπτης</span>, «observador»), aquele que tudo vê, onividente (Sb 4127, 18 <span class=\"greek\">Ἥλιον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">παντεπόπτην</span> <span class=\"greek\">δεσπότην</span>; Vett. Val. 1, 4; 331, 20 [<span class=\"greek\">Ἥλιος</span>]; papiros mágicos [TSchermann, Griech. Zauberpap. 1909, 28f]; 2 Macc 9:5; Ps.-Clem., Hom. 4, 14; 23; 5, 27; 8, 19; SibOr, Fgm. 1, 4, variante textual.—Os gregos chamam Zeus <span class=\"greek\">ὁ</span> <span class=\"greek\">πανόπτης</span> [por exemplo, Aeschyl., Eum. 1045] ou <span class=\"greek\">παντόπτης</span> [por exemplo, Aeschyl., Suppl. 139; Soph., Oed. C. 1085]), acerca de Deus: <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">δεσπότης</span>, 1 Cl 55:6. <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">θεός</span>, 64; Pol 7:2.—Ver DELG s.v. <span class=\"greek\">ὄπωπα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάντῃ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάντῃ</span> (<span class=\"greek\">πᾶς</span>; quanto à grafia, ver Mlt.-H. p. 84; B-D-F §26; W-S. §5, 11c), advérbio (Hom. e posteriores; especialmente <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 1, 4 e outros; inscrições, papiros; Sir 50:22; 3 Macc 4:1; Jos., Ant. 14, 183; Just., A II, 13, 2; 15, 4; Ath., R. 1 p. 48, 15 e outros), relativo a todas as considerações ou posições possíveis, em todos os sentidos: <span class=\"greek\">π</span>. <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πανταχοῦ</span>, «Em todos os sentidos e em toda parte» (B-D-F §103; Rob. 300), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:3</a>.—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάντοθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάντοθεν</span>, advérbio (<span class=\"greek\">πᾶς</span>; Hom. e posteriores; inscrições, papiros, LXX, En; JosAs 3:10; EpArist; Jos., Ant. 14, 442), relativo à extensão a partir de uma origem em todos os lados, de todas as direções, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:43</a>; por todos os lados, completamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a>; cf. PAmh 51, 27 [88 a.C.]; 3 Macc 3:25; EpArist 69; 115; 142; especialmente 57; Jos., Bell. 4, 587).—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντοκρατορικός, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντοκρατορικός</span>, <span class=\"greek\">όν</span> (formado de <span class=\"greek\">παντοκράτωρ</span> em consequência da ideia de que esse substantivo, por designar um agente [ver EFraenkel, Geschichte der griech. Nomina agentis auf-<span class=\"greek\">τήρ</span>,-<span class=\"greek\">τωρ</span>,-<span class=\"greek\">της</span>, 1910/12], não poderia ser empregado com um neutro [ver <span class=\"greek\">παντοκράτωρ</span>]), todo-poderoso, onipotente; acerca de Deus: <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">βούλημα</span> <span class=\"greek\">αὐτοῦ</span>, «A sua vontade onipotente», 1 Cl 8:5. <span class=\"greek\">τῷ</span> <span class=\"greek\">παντοκρατορικῷ</span> (conjectura em lugar de <span class=\"greek\">παντοκράτορι</span> do manuscrito) <span class=\"greek\">καὶ</span> <span class=\"greek\">παναρέτῳ</span> <span class=\"greek\">ὀνόματί</span> <span class=\"greek\">σου</span>, 60:4 (segundo a leitura de G-H-Z).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντοκράτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντοκράτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">κρατέω</span>; Kaibel 815, ver abaixo; Porphyr., Philos. Ex. Orac. ed. GWolff 1856, p. 145, linha 157 = Theosophien 27 p. 174, 4; SEG VIII, 548, 2 [I a.C.], feminino; CIG 2569, 12; Sb 4127, 19, referente ao deus-sol egípcio Mandulis; sobre Hermes, PGM 7, 668; também Kaibel 815, 11 [II d.C.] <span class=\"greek\">π</span>. <span class=\"greek\">Ἐριούνιε</span> [Hermes]; PMich 155, 3 [II d.C.]; PLips 40 II, 13; PGM 4, 272; 969 [ver New Docs 3, 118]; HGraillot, Les Dieux tout-puissants, Cybèle et Attis: RevArch 58, 1904 I 331ff; Cumont3 230f.—Muito mais frequente em escritos judaicos [LXX.—Ver ZTalshir, JQR 78, ’87, 57–75; TestSol, TestAbr, ParJer; GrBar 1:3; EpArist, Philo; Sib-Or 1, 66 e Fgm. 1, 8.—Não encontrado em Joseph.] e cristãos: Iren. 1, 9, 2 [Harv. I 82, 4]; Theoph. Ant. 2, 3 [p. 100, 1]. <span class=\"greek\">π</span>. referente ao Demiurgo em especulação gnóstica, Iren. 1, 11, 1 [Harv. I 101, 2]), o Todo-Poderoso, o Onipotente (ser), apenas acerca de Deus (como tradução de <span class=\"hebrew\" dir=\"rtl\">צְבָאוֹת</span> [Orig., C. Cels. 5, 45, 46] e <span class=\"hebrew\" dir=\"rtl\">שַׁדַּי</span>): <span class=\"greek\">π</span>. <span class=\"greek\">θεός</span> (3 Macc 6:2; Just., D. 38, 2 e outros; Mel., P. 45, 322), 1 Cl ins; <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">θεός</span> (2 Macc 8:18), 2:3; 32:4; 62:2; AcPl Ha 6, 14; <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:14</a>; 19:15; AcPlCor 2:12. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>., 2:9. <span class=\"greek\">θεὸς</span> <span class=\"greek\">π</span>. (Jer 3:19), Pol ins; AcPlCor 1:11. <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">παντοκτίστης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀόρατος</span> <span class=\"greek\">θεός</span>, Dg 7:2; <span class=\"greek\">κύριος</span> <span class=\"greek\">π</span>. (frequente na LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:18</a>. (<span class=\"greek\">ὁ</span>) <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. (= <span class=\"hebrew\" dir=\"rtl\">י״י</span> <span class=\"hebrew\" dir=\"rtl\">אֱלֹהֵי</span> <span class=\"hebrew\" dir=\"rtl\">הַצְּבָאוֹת</span>.—Hos 12:6; Am 3:13; 4:13; 5:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:8</a>; 4:8; 11:17; 15:3; 16:7; 21:22; MPol 14:1; <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:6</a>; <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">π</span>., MPol 19:2 (cf. Just., D. 139, 4). Deus é interpelado em oração eucarística como <span class=\"greek\">δέσποτα</span> <span class=\"greek\">π</span>., D 10:3 (cf. 3 Macc 2:2 <span class=\"greek\">μόναρχε</span> <span class=\"greek\">παντοκράτωρ</span>).—<span class=\"greek\">νουθέτημα</span> <span class=\"greek\">παντοκράτορος</span>, 1 Cl 56:6 (Job 5:17).—Encontram-se o genitivo e o dativo (singulares), idênticos em todos os gêneros, usados com o neutro <span class=\"greek\">ὄνομα</span>. Isso se torna possível (ver <span class=\"greek\">παντοκρατορικός</span>) porque o nome de Deus equivale quase ao próprio ser de Deus (ver <span class=\"greek\">ὄνομα</span> 1d). <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντοκράτορος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξου</span> <span class=\"greek\">ὀνόματος</span>, Hv 3, 3, 5. A leitura manuscrita <span class=\"greek\">τῷ</span> <span class=\"greek\">παντοκράτορι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παναρέτῳ</span> <span class=\"greek\">ὀνόματί</span> <span class=\"greek\">σου</span>, 1 Cl 60:4 (ver <span class=\"greek\">παντοκρατορικός</span>), é mais difícil, pois aqui o nome e Deus são separados por <span class=\"greek\">σου</span>.—FKattenbusch, Das apostolische Symbol II 1900, 520ff; Dodd 19; HHommel, TLZ 79, ’54, 283f. Pantokrator: Theologia Viatorum 5, ’53/54; OMontevecchi, Studi in Onore di ACalderini e RParibeni II, ’56, 401–32.—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M. DDD ‘Almighty’ 36–41. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παντοκτίστης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παντοκτίστης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πᾶς</span> [*<span class=\"greek\">παντ</span>], <span class=\"greek\">κτίστης</span>), criador do universo, com <span class=\"greek\">παντοκράτωρ</span>, Dg 7:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάντοτε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάντοτε</span>, advérbio de tempo (sobre a formação, Schwyzer I 629; grego helenístico e moderno; Dionys. Hal. e posteriores; Peripl. Eryth. 29; Epict., Ench. 14, 1; Dio Chrys. 15 [32], 37; Herodian 3, 9, 8; Artem. 4, 20; Plut.; Athen.; Diog. L.; OGI 458, 76 [I a.C.], SIG 814, 37 [67 d.C.]; BGU 1123, 8 [I a.C.]; PGiss 17, 4; 72, 11 [II d.C.]; Wsd 11:21; 19:18; TestSol, Test12Patr; JosAs 7:6; SyrBar 12:2; Jos., Bell. 3, 42; Just., D. 49, 7; 93, 4; Ath., R. 1 p. 49, 1 e outros.—Os aticistas preferiam <span class=\"greek\">ἑκάστοτε</span>, <span class=\"greek\">διαπαντός</span> ou <span class=\"greek\">ἀεί</span> [Phryn. 103 Lob.]), sempre, em todos os momentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:11</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:7</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:31</a>; 18:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:34</a>; 7:6 (sete ocorrências em J); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:4</a>; 15:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:14</a> (27 ocorrências em Paulo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a> (não encontrado em Atos nem nas epístolas católicas; B-D-F §105; cf. Rob. 300); Dg 11:4; IEph 4:2; Hv 1, 1, 7 (24 ocorrências em Hermas).—B. 984. DELG s.v. <span class=\"greek\">πᾶς</span>. 35–41. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάντως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάντως</span>, advérbio (<span class=\"greek\">πᾶς</span>; Hom. e posteriores; especialmente <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψου</span> 1, 2; inscrições, papiros, LXX; TestAbr B 13 p. 117, 25 [Stone p. 82]; TestJos 10:4; Philo, Joseph.; Ar. 13, 7; Just.; Tat. 16, 2; Ath., R. 5 p. 53, 15 e outros; empréstimo no hebraico rabínico).<br>\n① Relativo a forte suposição, de todos os modos, certamente, provavelmente, sem dúvida, com <span class=\"greek\">ὡς</span> aparentemente conservando sua força (Pla., Gorg. 527a; Herodas 7, 89; Diod S 20, 29, 3; Ps.-Demetr. 84; Ps.-Callisth. 2, 32, 3; SIG 762, 30; BGU 248, 12; PFlor 262, 11; POxy 1676, 15; Tob. 14:8 BA; 2 Macc 3:13; Jos., Vi. 48, C. Ap. 2, 140; Ar. 13, 7; Just.; Tat. 16, 2): <span class=\"greek\">πάντως</span> <span class=\"greek\">φονεύς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">οὗτος</span>, «Certamente este homem é assassino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:4</a>. <span class=\"greek\">πάντως</span> <span class=\"greek\">ἐρεῖτέ</span> <span class=\"greek\">μοι</span>, «Certamente me direis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:23</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:21</a>, variante textual; 21:22 (sobre todas essas ocorrências, exceto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:21</a>, variante textual, ver 3 abaixo). <span class=\"greek\">ἢ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">πάντως</span> <span class=\"greek\">λέγει</span>; «Ou não estará ele certamente falando em nosso interesse?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:10</a>. <span class=\"greek\">πάντως</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πειρασμόν</span> <span class=\"greek\">τινα</span> … <span class=\"greek\">βραδύτερον</span> <span class=\"greek\">λαμβάνεις</span>, «Sem dúvida é por causa de alguma tentação que recebes (uma resposta) lentamente», Hm 9:7. <span class=\"greek\">πάντως</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεσπότης</span>, «De todos os modos o Senhor deseja», Hs 9, 9, 4. Provavelmente 5, 7, 4; 7:4b pertencem a esta acepção (mas ver 3 abaixo). Em 7:5, <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πάντως</span> provavelmente significa «e especialmente assim».<br>\n② Relativo à abrangência, inteiramente, totalmente, completamente, Hs 1:5; B 1:4. <span class=\"greek\">πάντως</span> … <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">αὐτήν</span>, «Visto que (Jesus) a conhecia plenamente», GMary 463, 23f.<br>\n③ Expressão de conclusão inevitável em vista dos dados apresentados, naturalmente, é claro. Esse sentido foi proposto para Hv 1, 2, 4; Hs 5, 7, 4; 7:4b (mas talvez [latim fortasse em ambas as passagens de Hs] conforme HCadbury, JBL 44, 1925, 223ff, que sugere a mesma tradução para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:22</a>; 28:4; ver 1 acima); contudo, a acepção 1 parece fazer justiça ao contexto.<br>\n④ Expressão de estimativa mínima possível numa escala de abrangência, pelo menos: <span class=\"greek\">ἵνα</span> <span class=\"greek\">πάντως</span> <span class=\"greek\">τινὰς</span> <span class=\"greek\">σώσω</span>, «Para salvar ao menos alguns», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:22</a> (embora «por todos e quaisquer meios» também seja provável aqui).<br>\n⑤ Com um marcador negativo.<br>\nⓐ De modo algum (Theognis 305 D-B. <span class=\"greek\">τοὶ</span> <span class=\"greek\">κακοὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πάντως</span> <span class=\"greek\">κακοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">γαστρὸς</span> <span class=\"greek\">γεγόνασιν</span>; Just., D. 57, 2): <span class=\"greek\">πάντως</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">θέλημα</span>, «Ele não estava absolutamente disposto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:12</a>. Cf. Dg 9:1. Também como resposta a uma pergunta, «De modo algum» (assim PVat. A, 15 = Witkowski2 p. 65), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:9</a> (o texto é incerto; ver B-D-F §433, 2; Rob. 423). Hs 7:4a.<br>\nⓑ De maneira nenhuma (B-D-F §433, 2 e 3, com referência a Ps.-Clem., Hom. 4, 8; 19, 9; 20, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:10</a>.—DELG s.v. <span class=\"greek\">πᾶς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάνυ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάνυ</span>, advérbio de <span class=\"greek\">πᾶς</span> (Aeschyl., Thu. e posteriores), grau elevado numa escala de extensão, inteiramente, muito, usado com outras palavras.<br>\nⓐ Com verbos (Aeschyl. e outros; SIG 798, 5; PGen 74, 23; PFlor 252, 12; TestGad 1:5): <span class=\"greek\">π</span>. <span class=\"greek\">σωφρονεῖν</span>, «Demonstrar bom senso em todos os aspectos», 1 Cl 1:3.<br>\nⓑ Com adjetivos (Aeschyl. e outros; SIG 890, 15; PHib 27, 19 [III a.C.]; 2 Macc 15:17; TestAbr A 1 p. 77, 3 [Stone p. 2], B 2 p. 105, 9 [Stone p. 58]; TestJos 9:5; Philo, Aet M.; Jos., Bell. 3, 367; Just., D. 131, 3; Tat. 6, 1 e outros): <span class=\"greek\">πάνυ</span> <span class=\"greek\">ἱλαρός</span>, «Muito satisfeito», Hs 6, 1, 6.<br>\nⓒ Com advérbios (Aristoph., X. e outros; 2 Macc 9:6; 12:43; 13:8; Jos., Vi. 91; Tat. 1, 1; 34, 3): <span class=\"greek\">π</span>. <span class=\"greek\">σαφῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιμελῶς</span>, Dg 1.<br>\nⓓ Com artigo: <span class=\"greek\">Παπία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάνυ</span>, «Do renomado Pápias», Papias (6). Ver L-S-J-M s.v. <span class=\"greek\">πάνυ</span> II (por exemplo, Thu. 8, 1).—DELG s.v. <span class=\"greek\">πᾶς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παπίας, α</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Παπίας</span>, <span class=\"greek\">α</span> e <span class=\"greek\">ου</span> (nome próprio na Ásia Menor, ver PKretschmer, Einleitung in die Geschichte der griechischen Sprache, 1896, 345f [= 1970, 375f]; índice OGI; papiros), Pápias, bispo de Hierápolis na Frígia (I/II d.C.), Papias (1:4 e outros).—Zahn, Forsch. 6, 109–57; Bihlmeyer, xlvf.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρά</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρά</span> (Hom. e posteriores. Sobre elisão, ver B-D-F §17; Rob. 208), preposição empregada com três casos (Kühner-G. §440; Schwyzer II 491–98; B-D-F §236–38; Rob. 612–16. Bibliografia adicional, ver <span class=\"greek\">ἀνά</span>, início; também HRau, De praepositionis <span class=\"greek\">παρά</span> usu: GCurtius, Studien etc. III 1870).<br>\nA. Com genitivo, que quase sempre, como em Hom., Hdt., Pla., X. e outros, denota uma pessoa e indica que algo procede dessa pessoa (Hs 2:3 é uma exceção).<br>\n① Marcador de extensão a partir do lado de alguém, de, da parte de, com sentido local preservado, usado com verbos de vir, ir, enviar, originar-se, sair etc. (TestAbr A 2 p. 78, 30 [Stone p. 4] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">βασιλέως</span> <span class=\"greek\">ἀπεστάλην</span>; Lucian, Demon. 13 <span class=\"greek\">ἀπιὼν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῦ</span>): <span class=\"greek\">ἐκπορεύεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:26b</a>. <span class=\"greek\">ἐξέρχεσθαι</span>, 16:27; 17:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:1</a>; 6:19. <span class=\"greek\">ἔρχεσθαι</span>, 8:49. <span class=\"greek\">παραγίνεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:43</a>. <span class=\"greek\">πέμπειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:26a</a>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> … <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἀποσταλέντος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτήν</span> (= <span class=\"greek\">Μαρίαν</span>), AcPlCor 2:5. <span class=\"greek\">εἶναι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Ser proveniente de alguém» (cf. Job 21:2, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:46</a>; 7:29; 9:16, 33; 17:7.<br>\n② Marcador de quem origina ou dirige, da parte de, de (Appian, Bell. Civ. 4, 100 §420 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span>; TestJob 38:8 <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span>): <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">αὕτη</span>, «Isto procedeu do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:11</a> (ambos Ps 117:23). Com dupla negação: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀδυνατήσει</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> (ver <span class=\"greek\">ἀδυνατέω</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:37</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λελαλημένα</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span>, «Aquilo que lhe foi dito (pelo anjo) por ordem do Senhor», v. 45. <span class=\"greek\">ἀπεσταλμένος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span>, João Batista não foi, como Jesus, enviado da própria presença de Deus, mas alguém cuja vinda foi ocasionada por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:6</a> (cf. 2 Macc 11:17). <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτῆς</span> <span class=\"greek\">φέρει</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πτελέας</span>, «Ela (isto é, a videira) produz fruto que vem tanto de si mesma quanto do olmo», Hs 2:3. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>, ver <span class=\"greek\">κρίσις</span> 1b<span class=\"greek\">β</span>.<br>\n③ Marcador do ponto a partir do qual uma ação se origina, de.<br>\nⓐ Depois de verbos:<br>\n<span class=\"greek\">α</span>. De pedir, solicitar: <span class=\"greek\">αἰτεῖν</span> e <span class=\"greek\">αἰτεῖσθαι</span> (cf. X., An. 1, 3, 16, Hell. 3, 1, 4; SIG 785, 9f; PFay 121, 12ff; Tob 4:19 BA e outros; LXX; TestAbr A 9 p. 87, 2 [Stone p. 22]; TestJob 20:2; ParJer 7:14; Jos., Ant. 15, 92), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:20</a>, variante textual (em lugar de <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:2</a>; 9:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:15</a>, variante textual (em lugar de <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span>); 1 Cl 36:4 (Ps 2:8); Hm 9:2, 4; Dg 1. <span class=\"greek\">ζητεῖν</span> (Tob 4:18; Sir 7:4; cf. 1 Macc 7:13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:16</a>; 12:48.<br>\n<span class=\"greek\">β</span>. De tomar, aceitar, receber: <span class=\"greek\">λαμβάνειν</span> (grego clássico; Appian, Mithrid. 88 §397; SIG 546 B, 23 [III a.C.]; Jdth 12:15; Sus 55 Theod.; 1 Macc 8:8; 11:34; 4 Macc 12:11; TestJob 11:5; JosAs 24:11; Just., A I, 39, 5 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:34</a>, 41, 44; 10:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:33</a>; 3:5; 17:9; 20:24; 26:10 (Jos., Ant. 14, 167 <span class=\"greek\">λαβὼν</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">σου</span> [= <span class=\"greek\">τ</span>. <span class=\"greek\">ἀρχιερέως</span>]; 11, 169); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>; 2J 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:28</a>; Hs 1:8; 8, 3, 5; GJs 20, 2, códices. <span class=\"greek\">ἀπολαμβάνειν</span> (SIG 150, 19f [texto restaurado; IV a.C.]; 4 Macc 18:23), Hv 5:7. <span class=\"greek\">παραλαμβάνειν</span> (Hdt. e outros; frequente em inscrições; POxy 504, 14 e outras ocorrências em papiros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13</a>; 4:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>. <span class=\"greek\">δέχεσθαι</span> (Thu. 1, 20, 1 e outros; 1 Macc 15:20; TestJob 11:12; cf. <span class=\"greek\">διαδέχεσθαι</span> em Ath. 37, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:18a</a>. <span class=\"greek\">κομίζεσθαι</span> (SIG 244 I, 5ff [IV a.C.]; Gen 38:20; 2 Macc 7:11; Ath. 12, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:8</a>. <span class=\"greek\">εὑρεῖν</span> (SIG 537, 69; 1099, 28; cf. <span class=\"greek\">εὑρίσκω</span> 3, final), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:18</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Ter recebido algo de alguém» (1 Esdr 6:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:14</a>; cf. Hv 3, 9, 8. <span class=\"greek\">γίνεταί</span> <span class=\"greek\">μοί</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Recebo alguma coisa de alguém» (ático), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. <span class=\"greek\">ἔσται</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">χάρις</span> … <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Ἰησοῦ</span>, 2J 3 (cf. X., An. 7, 2, 25). <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστευθέντες</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔργον</span>, «Aqueles a quem Deus confiou uma tarefa», 1 Cl 43:1 (cf. Polyb. 3, 69, 1; SIG 1207, 12f). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">πλουτίζεσθαι</span>, «Receber riqueza do Senhor», Hs 2:10.—De modo semelhante, na compra, o vendedor é introduzido por <span class=\"greek\">παρά</span>: comprar de alguém; <span class=\"greek\">ἀγοράζειν</span> (ver <span class=\"greek\">ἀγοράζω</span> 1, final), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>. <span class=\"greek\">ὠνεῖσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a>. <span class=\"greek\">ἄρτον</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Receber sustento de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>.<br>\n<span class=\"greek\">γ</span>. De aprender, chegar a conhecer, ouvir, perguntar: <span class=\"greek\">ἀκούειν</span> (ver <span class=\"greek\">ἀκούω</span> 1b<span class=\"greek\">β</span> e 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:40</a>; 6:45; 7:51; 8:26, 40; 15:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:22</a>; 28:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:13</a>; 2:2; AcPlCor 1:6; <span class=\"greek\">ἀκριβοῦν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a>, 16. <span class=\"greek\">ἐξακριβάζεσθαι</span>, Hm 4, 2, 3. <span class=\"greek\">ἐπιγινώσκειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:8</a>. <span class=\"greek\">μανθάνειν</span> (desde Aeschyl., Ag. 858; Jos., C. Ap. 2, 176; Sir 8:8f; 2 Macc 7:2, variante textual; 3 Macc 1:1; Just., A I, 23, 1 e D. 78, 1 e outros; Ath. 7, 2; 22, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14</a>. <span class=\"greek\">πυνθάνεσθαι</span> (Hdt. 3, 68; X., Cyr. 1, 6, 23; Pla., Rep. 5, 476e; SIG 1169, 30; 2 Ch 32:31), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:52</a> (variante textual sem <span class=\"greek\">παρά</span>); B 13:2 (Gen 25:22).<br>\nⓑ Em função adjetival: <span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Feito, dado etc. por alguém».<br>\n<span class=\"greek\">α</span>. Com substantivo (funciona como genitivo: Pla., Symp. 197e <span class=\"greek\">ὁ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">λόγος</span>, «A expressão proferida por alguém»; X., Hell. 3, 1, 6 <span class=\"greek\">δῶρον</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">βασιλέως</span>, Mem. 2, 2, 12 <span class=\"greek\">ἡ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">εὔνοια</span>, Cyr. 5, 5, 13 <span class=\"greek\">τὸ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ἀδίκημα</span>, «O delito cometido por mim»; Polyb. 3, 69, 3 <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σωτηρία</span>; Polyaenus 3, 9, 28 <span class=\"greek\">ἡ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">στρατηγοῦ</span> <span class=\"greek\">ἀρετή</span>; SIG 543, 27; Ex 4:20; 14:13; Philo, Plant. 14; Jos., Ant. 12, 400; Just., A I, 32, 8 e D. 92, 1 e outros; Ath. 7, 1), <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">διαθήκη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:27</a> (Is 59:21).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:12</a>, variante textual; 22, variante textual.<br>\n<span class=\"greek\">β</span>. Em função substantiva:<br>\n<span class=\"hebrew\" dir=\"rtl\">א</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Aquilo que alguém dá, dádivas de alguém» (X., Mem. 3, 11, 13; Jos., Bell. 2, 124, Ant. 8, 175; Tat. 32, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:18b</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῆς</span>, «Os bens dela, o que ela possuía», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26</a> (cf. IPriene 111, 177). <span class=\"greek\">τὰ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">ζώσης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μενούσης</span>, «(A ajuda que recebi) de uma voz viva, de alguém contemporâneo», Papias (2:4).<br>\n<span class=\"hebrew\" dir=\"rtl\">ב</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «Os enviados de alguém» (<span class=\"greek\">οἱ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">βασιλέω</span> <span class=\"greek\">πρέσβει</span>, X., Hell. 1, 3, 9; frequente nas inscrições, por exemplo OGI 5, 50, enviados de Ptolomeu; expressão completa <span class=\"greek\">οἱ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πρεσβείς</span>, OGI 8 VI, 108–9; Schwyzer II 498; B-D-F §237, 2); <span class=\"greek\">οἱ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span> (1 Macc 2:15; 1 Esdr 1:15), 1 Cl 12:4.—O grego koiné também usa essa expressão para indicar outras pessoas intimamente ligadas a alguém, por exemplo, família, parentes (PGrenf II, 36, 9 [II a.C.]; POxy 805 [I a.C.]; 298, 37 [I d.C.]; CPR I, 179, 16; 187, 7; Sb 5238, 19 [I d.C.]; Sus 33; 1 Macc 13:52; Jos., Ant. 1, 193. Outros exemplos dos papiros em Mlt. 106f; Rossberg [ver <span class=\"greek\">ἀνά</span>, início] 52), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:21</a> (ver CBruston/PFarel: RTQR 18, 1909, 82–93; AWabnitz, ibid. 221–25; SMonteil, ibid. 19, 1910, 317–25; JMoulton, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:21</a>: ET 20, 1909, 476; GHartmann, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20f</a>: BZ 11, 1913, 248–79; FZorell, Zu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20</a>, 21: ZKT 37, 1913, 695–7; JBelser, Zu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20f</a>: TQ 98, 1916, 401–18; Rdm.2 141; 227.—Ver também <span class=\"greek\">ἐξίστημι</span> 2a).<br>\nB. Com dativo, caso que expressa associação estreita.<br>\n① Marcador de proximidade espacial, junto a, ao lado de, perto de, com, conforme o ponto de vista sob o qual se encara a relação.<br>\nⓐ Perto de, ao lado de.<br>\n<span class=\"greek\">α</span>. Com coisas (Synes., Ep. 126 p. 262a; Kaibel 703, 1; POxy 120, 23; 2 Km 10:8; 11:9; Jos., Ant. 1, 196): <span class=\"greek\">εἱστήκεισαν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a>. <span class=\"greek\">κεῖσθαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πύργῳ</span>, Hv 3, 5, 5.<br>\n<span class=\"greek\">β</span>. Com pessoas: <span class=\"greek\">ἔστησεν</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτῷ</span>, «Fê-lo (isto é, a criança) ficar em pé ao seu lado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:47</a>.<br>\nⓑ Na casa, cidade, companhia etc. de alguém (Demetr.: 722 Fgm. 1, 5 e outros <span class=\"greek\">παρὰ</span> <span class=\"greek\">Λάβαν</span>).<br>\n<span class=\"greek\">α</span>. Casa: <span class=\"greek\">ἀριστᾶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:37</a>. <span class=\"greek\">καταλύειν</span>, 19:7 (Pla., Gorg. 447b; Demosth. 18, 82). <span class=\"greek\">μένειν</span> (JosAs 20:8; Jos., Ant. 1, 298; 299), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:43</a>; 18:3; 21:8. <span class=\"greek\">ξενίζεσθαι</span>, 10:6; 21:16 (<span class=\"greek\">ξενίζω</span> 1). Assim, provavelmente, também <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτῷ</span>, «Cada um em sua própria casa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a> (cf. Philo, Cher. 48 <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτοῖς</span>, Leg. ad Gai. 271). <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀπέλιπον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Τρῳάδι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Κάρπῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a>.<br>\n<span class=\"greek\">β</span>. Cidade: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a>. Assim, provavelmente, também <span class=\"greek\">ἦσαν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἀδελφοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:25</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:16</a> (onde a congregação de Laodiceia é contrastada com a de Colossos).<br>\n<span class=\"greek\">γ</span>. Outros usos: <span class=\"greek\">παρὰ</span> <span class=\"greek\">Ἰουδαίοις</span>, «Entre os judeus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a>. <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐπιμεῖναι</span>, «Permanecer com eles», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:14</a>; cf. 21:7. <span class=\"greek\">οἱ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πρεσβύτεροι</span>, «Os presbíteros entre vós», 1 Cl 1:3.—<span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span>, «Com o Pai» (proximidade espacial), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:38a</a>; cf. 17:5 (Synes., Kingship 29 p. 31d: a filosofia tem sua morada <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> e, se o mundo recusa recebê-la quando desce à terra, <span class=\"greek\">μένει</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span>). Sobre Jesus: <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">μένων</span>, «Enquanto eu permanecia convosco (na terra)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:25</a>. Sobre o Espírito: <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">μένει</span>, v. 17. Sobre o Pai e o Filho em sua relação com o cristão fiel: <span class=\"greek\">μονὴν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ποιησόμεθα</span>, «Faremos nossa morada com ele», v. 23.<br>\n<span class=\"greek\">δ</span>. Figuradamente: <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, «Perante o tribunal de alguém» (Demosth. 18, 13 <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">καθιστάναι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>; Appian, Maced. 11 §8 <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">κρίσιν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>, variante textual. Estreitamente relacionado está:<br>\n② Marcador de alguém cujo ponto de vista é relevante, aos olhos de, no julgamento de alguém (Soph., Hdt.; PSI 435, 19 [258 a.C.] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βασιλεῖ</span>): <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, <span class=\"greek\">δίκαιος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «Justo aos olhos de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:13</a> (cf. Job 9:2; Jos., Ant. 6, 205; Ath. 31, 2 <span class=\"greek\">εὐδοξοῦμεν</span> … <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>).—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:8</a>. <span class=\"greek\">θυσία</span> <span class=\"greek\">δεκτὴ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, Hs 5, 3, 8. <span class=\"greek\">ἔνδοξος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, Hm 2:6; Hs 5, 3, 3; 8, 10, 1; 9, 27, 3; 9, 28, 3; 9, 29, 3.—9, 7, 6.—Segundo o julgamento humano (Jos., Ant. 7, 84; Just., A I, 20, 3), 8, 9, 1. <span class=\"greek\">τί</span> <span class=\"greek\">ἄπιστον</span> <span class=\"greek\">κρίνεται</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span>; «Por que isso é considerado incrível entre vós?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:8</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἦτε</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">φρόνιμοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>; cf. 12:16 (ver Pr 3:7 <span class=\"greek\">μὴ</span> <span class=\"greek\">ἴσθι</span> <span class=\"greek\">φρόνιμος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">σεαυτῷ</span>).—A ideia de «no julgamento» passa ao sentido mais simples de «com» (PsSol 9:5 <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίῳ</span>; Jos. Himerius, Or. 8 [=23], 10 <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῖς</span>, «com os deuses»): <span class=\"greek\">εὑρεῖν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, «Achar favor junto de alguém» (Ex 33:16; cf. Num 11:15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:30</a>; Hs 5, 2, 10. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a>. <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχειν</span> (Ex 33:12), Hm 5, 1, 5. <span class=\"greek\">προέκοπτεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώποις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:52</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ταπεινοφροσύνη</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἰσχύει</span>, <span class=\"greek\">τί</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">ἁγνὴ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">δύναται</span>, «Quão forte é a humildade perante Deus, o que pode realizar perante Deus o amor puro», 1 Cl 21:8.<br>\n③ Marcador de referência pessoal, ao lado de, com, quase equivalente ao dativo propriamente dito (Ps 75:13): <span class=\"greek\">δυνατόν</span> ou <span class=\"greek\">ἀδύνατον</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, «Possível ou impossível para alguém» (Gen 18:14; Just., A I, 33, 2; Ath., R. 9 p. 58, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:26</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:27</a>abc; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:37</a>, variante textual; 18:27ab; 1 Cl 27:2.—AFridrichsen, SymbOsl 14, ’35, 44–46. Estreitamente relacionado no significado está:<br>\n④ Marcador de ligação de uma qualidade ou característica com uma pessoa, com: (<span class=\"greek\">οὐκ</span>) <span class=\"greek\">ἔστιν</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, «Algo (não) está com ou em alguém», «Alguém (não) tem algo a ver com alguma coisa» (Demosth. 18, 277 <span class=\"greek\">εἰ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοί</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἐμπειρία</span>; Gen 24:25; Job 12:13; Ps 129:4 <span class=\"greek\">παρὰ</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱλασμός</span> <span class=\"greek\">ἐστιν</span>; Just., D. 82, 1 <span class=\"greek\">παρὰ</span> … <span class=\"greek\">ἡμῖν</span> … <span class=\"greek\">χαρίσματα</span>): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">προσωπολημψία</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:11</a> (TestJob 43, 13). Cf. 9:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a>. De modo semelhante, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17</a>.<br>\n⑤ Marcador de relação com foco mais restrito, entre, perante: <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτοῖς</span>, «Entre si mesmos» (Philo, Cher. 48), <span class=\"greek\">διαλογίζεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:25</a>, variante textual (cf. Demosth. 10, 17 <span class=\"greek\">γιγνώσκειν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὑτῷ</span>; Epict., Ench. 48, 2).—Em <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">μενέτω</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:24</a>, o sentido de <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> não é seguro: «Que a pessoa permaneça nessa condição (a mesma em que estava quando foi chamada à salvação) diante de Deus»; provavelmente procura lembrar aos cristãos aquele perante quem eles não podem sequer aparentar inferioridade (inscrição: Mitt-Wilck, I/2, 4, 4 [13 a.C.] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">Ἑρμῇ</span>, «Diante de, aos olhos de»; Sb 7616 [II d.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">προσκύνημά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ποιῶ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">Σαράπι</span>, «Perante o Senhor Serápis»; 7661, 3 [cerca de 100 d.C.]; 7932, 7992, 6 [carta, II/III d.C.]). Ou talvez queira dizer simplesmente que, seja qual for a situação, a pessoa deve manter sua atenção voltada para Deus.<br>\nC. Com acusativo de pessoa ou coisa.<br>\n① Marcador de posição considerada em sua extensão (sem distinção entre responder <span class=\"greek\">παρά</span> à pergunta «onde?» ou «para onde?». Ver B-D-F §236, 1; Rob. 615).<br>\nⓐ Perto de, ao longo de: <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> (Pla., Gorg. 511e. Cf. SIG 1182; Jos., Ant. 2, 81), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:16</a>.<br>\nⓑ Na margem ou até a margem de algo.<br>\n<span class=\"greek\">α</span>. <span class=\"greek\">παρὰ</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">θάλασσαν</span>, «Junto ao mar (ou lago), à beira-mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1</a>; 5:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:6</a>, 32; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1</a>, 2. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>, «À beira da estrada» (X., An. 1, 2, 13; Plut., Lysander 450 [29, 4], um túmulo <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδόν</span>, «junto da estrada»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:35</a> (mas «na estrada» também é possível nas três passagens; ver d abaixo).<br>\n<span class=\"greek\">β</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, «Até a beira do mar (lago)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:13</a>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">ποταμόν</span>, «Até o rio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a>.<br>\nⓒ Em geral, perto de, junto a: <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span>, «Aos pés de alguém» (sentar, cair, colocar etc.; TestAbr A 17 p. 98, 16 [Stone p. 44]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38</a>; 8:35, 41; 10:39, variante textual; 17:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:35</a>, 37, variante textual; 5:2; 7:58; 22:3 (ver ET 30, 1919, 39f). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πὺργον</span>, «Ao lado da torre», Hs 9, 4, 8; 9, 6, 5; 8; 9, 7, 1; 9, 11, 6.—<span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰτέαν</span>, 8, 1, 2 (cf. TestAbr A 6 p. 83, 10 [Stone p. 14] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δρῦν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Μαμβρῆ</span>).<br>\nⓓ Na estrada: <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>, «Na estrada» (com movimento implícito; Aesop, Fab. 226 P. = 420 H.: <span class=\"greek\">πεσὼν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>; Phot., Bibl. 94 p. 74b, sobre Iambl. Erot. [Hercher I p. 222, 22] <span class=\"greek\">πίπτουσι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:4</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>; «na estrada» (sem movimento implícito; Theophr., HP 6, 6, 10: o açafrão gosta de ser pisado, <span class=\"greek\">διὸ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδοὺς</span> <span class=\"greek\">κάλλιστος</span>; Phot. p. 222, 29 H. [ver acima]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:12</a>. Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:35</a> (ver b<span class=\"greek\">α</span> acima).—<span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χεῖλος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, «Na praia, à beira-mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a> (TestAbr A 1 p. 78, 1 [Stone p. 4]; ApcEsdr 3:10; ApcSed 8:9).<br>\n② Marcador de extensão temporal, durante, de … até (Lucian, Catapl. 24 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βίον</span>, «Durante a vida dele»; POxy 472, 10; TestAbr A 20 p. 102, 26 [Stone p. 52] <span class=\"greek\">παρὰ</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">ὥραν</span>; Tat. 14, 2 <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἔζων</span> <span class=\"greek\">χρόνον</span>): <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐνιαυτόν</span>, «De ano em ano» (Plut., Cleom. 15, 1; cf. <span class=\"greek\">ἐνιαυτός</span> 1), B 10:7.<br>\n③ Marcador de vantagem comparativa, em comparação com, mais do que, além de: <span class=\"greek\">ἁμαρτωλοί</span>, <span class=\"greek\">ὀφειλέται</span> <span class=\"greek\">π</span>. <span class=\"greek\">πάντας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:2</a>, 4 (PSI 317, 6 [95 d.C.] <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντας</span>; Jos., C. Ap. 2, 234 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄλλους</span> <span class=\"greek\">ἅπαντας</span>; JosAs 10:6 <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάσας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">παρθένους</span>; Just., A I, 20, 3 <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀδίκως</span> <span class=\"greek\">μισούμεθα</span>). <span class=\"greek\">κρίνειν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμέραν</span> (ver <span class=\"greek\">κρίνω</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5</a>. <span class=\"greek\">π</span>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, B 11:9 (citação profética de origem desconhecida). <span class=\"greek\">π</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πνεύματα</span>, «Mais do que todos os demais espíritos», Hm 10, 1, 2. <span class=\"greek\">ἐλαττοῦν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινα</span>, «Tornar alguém inferior a outra pessoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:7</a>, 9 (ver <span class=\"greek\">ἐλαττόω</span> 1 e cf. PGrenf I, 42, 12 [II a.C.] <span class=\"greek\">ἐλαττουμένων</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δεῖνα</span>). <span class=\"greek\">εἶδος</span> <span class=\"greek\">ἐκλεῖπον</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">εἶδος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> (ver <span class=\"greek\">ἐκλείπω</span> 4), 1 Cl 16:3.—Depois de comparativo (Thu. 1, 23, 3; ApcEsdr 1:22; Tat. 2, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:4</a>; 3:3; 9:23; 11:4; 12:24; B 4:5 (cf. Da 7:7); Hv 3, 12, 1; Hs 9, 18, 2.—Quando há comparação, um de seus membros pode receber tão pouca atenção que é inteiramente desconsiderado, de sorte que «mais do que» se converte em «em lugar de», «antes que», com exclusão de (Plut., Mor. 984c; PsSol 9:9; EpArist 134; Just., A I, 22, 2): <span class=\"greek\">λατρεύειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κτίσει</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κτίσαντα</span>, «Servir à criação em vez do Criador», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:25</a> (cf. EpArist 139: os judeus adoram <span class=\"greek\">τὸν</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτίσιν</span>). <span class=\"greek\">δεδικαιωμένος</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐκεῖνον</span>, «Justificado antes que o outro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:14</a>. <span class=\"greek\">ἔχρισέν</span> <span class=\"greek\">σε</span> … <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μετόχους</span>, «Deus te ungiu, e não aos teus companheiros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:9</a> (Ps 44:8). <span class=\"greek\">ὑπερφρονεῖν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">φρονεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:3</a> (Plut., Mor. 83f <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δεῖ</span>). <span class=\"greek\">παρὰ</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">ἡλικίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a> (Plut., Rom. 25, 6 <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡλικίαν</span>; cf. <span class=\"greek\">ἡλικία</span> 2a).—<span class=\"greek\">παρὰ</span> <span class=\"greek\">δύναμιν</span>, «Além das próprias forças, dos próprios recursos» (ver <span class=\"greek\">δύναμις</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:3</a>.—Depois de <span class=\"greek\">ἄλλος</span> (Pla., Lach. 178b, Leg. 3, 693b; X., Hell. 1, 5, 5; Demosth. 18, 235), «Outro diferente de», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:11</a>.<br>\n④ Marcador de grau ligeiramente inferior numa comparação, exceto por, quase: <span class=\"greek\">παρὰ</span> <span class=\"greek\">μικρόν</span>, «Por pouco, quase» (ver <span class=\"greek\">μικρός</span> 1e<span class=\"greek\">γ</span>), Hs 8, 1, 14. Também <span class=\"greek\">παρά</span> <span class=\"greek\">τι</span> (cf. Vett. Val. 228, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:7</a> D; Hs 9, 19, 3.<br>\n⑤ Marcador de causalidade, por causa de (cf. Pind., O. 2, 65 <span class=\"greek\">κενεὰν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">δίαιταν</span>, «No interesse de» ou «por uma parca subsistência», contrastando sua escassez com o enorme trabalho exigido; Demosth. 4, 11; 9, 2; PRyl 243, 6; POxy 1420, 7): <span class=\"greek\">παρὰ</span> <span class=\"greek\">τό</span> seguido de acusativo, «Porque» (SIG 495, 130; UPZ 7, 13 [163 a.C.] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Ἕλληνά</span> <span class=\"greek\">με</span> <span class=\"greek\">εἶναι</span>.—Mayser II/1, 1926, 331; Gen 29:20; Ex 14:11), 1 Cl 39:5f (Job 4:20f). <span class=\"greek\">π</span>. <span class=\"greek\">τοῦτο</span>, «Por esse motivo» (Kühner-G. I 513, 3; Synes., Ep. 44 p. 185a; 57 p. 192d), ITr 5:2; IRo 5:1 (citação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:4</a>, onde Paulo emprega <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>). <span class=\"greek\">οὐ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">οὐ</span> (dupla negação como afirmação reforçada), «Não é por isso que é menos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:15f</a>.<br>\n⑥ Marcador daquilo que não corresponde ao esperado, contra, contrário a (Hom., Alc. e outros; inscrições, papiros, LXX; Just., Tat., Ath.—Schwyzer II 497): <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">διδαχήν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:17</a>. <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐλπίδα</span>, «Contra a esperança» (ver <span class=\"greek\">ἐλπίς</span> 1a), em jogo de palavras com <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλπίδι</span>, 4:18. <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> (Thu. 6, 17, 1; Pla., Rep. 5, 466d; Tat. 22, 2; Ath. 26, 2, R. 6 p. 54, 13), 1:26; 11:24. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> (Just., A II, 2, 4; Ath. 1, 3; cf. X., Mem. 1, 1, 18 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">νόμους</span>; PMagd 16, 5 [222 a.C.] <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">νόμους</span>; Jos., C. Ap. 2, 233; Just., A I, 68, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:13</a>. <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὅ</span>, «Contrário àquilo que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:8f</a> (Just., A I, 43, 8).<br>\n⑦ Marcador de uma quantidade inferior, menos (Hdt. 9, 33; Plut., Caesar 722 [30, 5]; Jos., Ant. 4, 176; POxy 264, 4 [I d.C.]): <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μίαν</span>, «Quarenta menos um = trinta e nove (açoites)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:24</a> (cf. Makkoth 3, 10 [tradução de HDanby, The Mishnah ’33, 407]).—Sobre <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτά</span>, ITr 11:1, ver <span class=\"greek\">παραυτά</span>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβαίνω</span>, futuro <span class=\"greek\">παραβήσομαι</span> na LXX; 2.º aoristo <span class=\"greek\">παρέβην</span>; particípio perfeito <span class=\"greek\">παραβεβηκώς</span> na LXX (Hom. e posteriores; inscrições, papiros, LXX, En, PsSol 18:10; TestJud 13:7; ApcSed 5:3; EpArist, Philo, Joseph., apologistas).<br>\n① Intransitivo, desviar-se, afastar-se, figuradamente: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>, «Desviar-se do caminho», 1 Cl 53:2 (Ex 32:8; Dt 9:12). Afastar-se de um ofício: <span class=\"greek\">ἀποστολή</span>, <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">παρέβη</span> <span class=\"greek\">Ἰούδας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:25</a> (sobre a construção com <span class=\"greek\">ἀπό</span>, cf. Dt 9:16; 17:20).<br>\n② Transitivo, transgredir, violar.<br>\nⓐ Com acusativo de alguma coisa, <span class=\"greek\">τὶ</span> (Aeschyl. e outros; Thu. 4, 97, 2; frequente em inscrições, papiros, LXX; Ar. 4, 2 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἰδίους</span> <span class=\"greek\">ὄρους</span>, sobre os corpos celestes; Just., A II, 5, 3 <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span>; Ath. 25, 3; <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> <span class=\"greek\">πίστιν</span>, Hippol., Ref. 9, 12, 16): <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> (Eur., Ion 231; Pla., Crito 53e; Sir 19:24; 1 Esdr 8:24, 84; 3 Macc 7:12; SibOr 3, 599f; Jos., C. Ap. 2, 176; Ath. 25, 4; Theoph. Ant. 2, 16 [p. 140, 17]), Hs 8, 3, 5. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (Epict. 3, 5, 8; Tob 4:5; 4 Macc 13:15; 16:24; Mel., P. 48, 343), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:3</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span>, v. 2; AcPlCor 2:37.<br>\nⓑ Empregado absolutamente (com «mandamentos» subentendido: Did., Gen. 101, 27. Cf. Iren. 1, 10, 1 [Harv. I 91, 11], acerca dos anjos caídos): <span class=\"greek\">παρέβησαν</span>, «Tornaram-se transgressores», B 9:4. Particípio <span class=\"greek\">ὁ</span> <span class=\"greek\">παραβαίνων</span>, «O transgressor», 2J 9, variante textual (Aristot., Pol. 1325b; plural: POxy 34 III, 12 [II d.C.]; Sir 40:14; Philo, Mos. 2, 49; Jos., C. Ap. 2, 215; Just., A II, 9, 1, D. 141, 1).—Ver <span class=\"greek\">παράβασις</span>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0267-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβάλλω</span>, futuro <span class=\"greek\">παραβαλῶ</span>; 2.º aoristo <span class=\"greek\">παρέβαλον</span>; particípio perfeito <span class=\"greek\">παραβεβλημένος</span>, 2 Macc 14:38 (Hom. e posteriores).<br>\n① Arremessar até o ponto em que uma entidade se encontra, lançar a, transitivo, especialmente sobre lançar forragem a animais (Il. 5, 369 e outros; Pla., Phdr. 247e; Cass. Dio 59, 14); acerca dos mártires: <span class=\"greek\">τούτοις</span> (isto é, <span class=\"greek\">τοῖς</span> <span class=\"greek\">θηρίοις</span>) <span class=\"greek\">σε</span> <span class=\"greek\">παραβαλῶ</span>, «Vou lançar-te a estes (isto é, às feras)», MPol 11:1. Passiva (cf. <span class=\"greek\">παραβληθῆναι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θηρίοις</span>: Cass. Dio 59, 10; Athen. 3, 84e; Just.), Dg 7:7.<br>\n② Expor a perigo, entregar, transitivo (Aristoph. e outros; Polyb. 40, 4, 2; POxy 533, 13 [II d.C.]; EpArist 281.—Igualmente na voz média): <span class=\"greek\">κινδύνῳ</span> <span class=\"greek\">ἑαυτόν</span>, «Expor-se ao perigo», 1 Cl 55:6.<br>\n③ Colocar alguma coisa ao lado de outra para compará-las, comparar, transitivo, extensão figurada da acepção 1 (Hdt. e outros; PFlor 312, 8 [I d.C.]; Philo, Leg. All. 3, 249 e outros; Jos., C. Ap. 2, 150; 279): <span class=\"greek\">ἐν</span> (instrumental) <span class=\"greek\">ποίᾳ</span> <span class=\"greek\">παραβολῇ</span> <span class=\"greek\">παραβάλωμεν</span> <span class=\"greek\">αὐτήν</span>; «Com que comparação/parábola podemos compará-lo (isto é, o Reino de Deus)?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a>, variante textual.<br>\n④ Aproximar-se de alguém ou de alguma coisa, chegar perto, intransitivo (Pla. e outros; frequente em papiros; com <span class=\"greek\">εἰς</span>, Polyb. 12, 5, 1; 16, 37, 7; 21, 8, 13; Diod S 1, 46, 7; 8; Plut., Demetr. 907 [39, 2]; PRyl 153, 5), especificamente como termo náutico, aproximar-se de navio, atravessar (Hdt. 7, 179; Ep. Phil. em Demosth. 12, 16; Jos., Ant. 18, 161 <span class=\"greek\">εἰς</span> <span class=\"greek\">Ποτιόλους</span> <span class=\"greek\">παραβαλών</span>): <span class=\"greek\">παρεβάλομεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Σάμον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:15</a>.—M-M.</p></section></article>"};
